  | 'inspect'
  | 'spawn_blue'
  | 'spawn_red'
  | 'plant_tree'
  | 'drop_fruit';

export interface Preset {
  id: string;
  name: string;
  badge: string;
  description: string;
  config: Partial<SimulationConfig>;
}

